require_once __DIR__.'/../includes/bootstrap.php';require_role('programme_officer');$user=current_user();$flashes=render_flashes();$currentPage='candidate_view';$pageTitle='Candidate Details';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$officerId=(int)($user['id']??$user['user_id']??0);$candidateId=(int)($_GET['id']??0);$cohortId=(int)($_GET['cohort_id']??0);if($officerId<=0||$candidateId<=0||$cohortId<=0){http_response_code(400);exit('Invalid request.');}$scope=po_scope($conn,'p','c');$sql="SELECT u.id,u.first_name,u.last_name,u.email,cp.status participant_status,cp.selected_at,cp.onboarded_at,cp.completed_at,c.id cohort_id,c.name cohort_name,c.status cohort_status,c.start_date cohort_start_date,c.end_date cohort_end_date,p.id programme_id,p.name programme_name,p.type programme_type FROM cohort_participants cp INNER JOIN users u ON u.id=cp.user_id INNER JOIN cohorts c ON c.id=cp.cohort_id INNER JOIN programmes p ON p.id=c.programme_id WHERE u.id=? AND c.id=? AND {$scope['condition']} LIMIT 1";$stmt=$conn->prepare($sql);$stmt->bind_param('iii',$candidateId,$cohortId,$officerId);$stmt->execute();$c=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$c){http_response_code(403);exit('Candidate not found or access denied.');}$fn=trim((string)($c['first_name']??''));$ln=trim((string)($c['last_name']??''));$name=trim($fn.' '.$ln)?:'Candidate';require __DIR__.'/_layout_start.php';?>
<div class="po-breadcrumb"><a href="<?= url('programme_officer/candidates.php') ?>">Candidates</a><i class="fas fa-chevron-right"></i><span><?= e($name) ?></span></div>
<div class="po-profile-hero"><div class="po-profile-hero__avatar"><?= e(po_initials($fn,$ln)) ?></div><div class="po-profile-hero__copy"><span class="po-profile-hero__eyebrow"><?= e($c['programme_name']) ?></span><h2><?= e($name) ?></h2><p><?= e((string)$c['email']) ?></p><div class="po-profile-hero__badges"><span class="po-status po-status--<?= e(po_status_class($c['participant_status'])) ?>"><?= e(po_status_label($c['participant_status'])) ?></span><span class="po-chip"><i class="fas fa-layer-group"></i> <?= e($c['cohort_name']) ?></span></div></div></div>
<div class="po-grid po-grid--2"><section class="po-card"><div class="po-card__header"><div><h3>Programme Placement</h3><p>Current programme and cohort context.</p></div></div><div class="po-card__body"><div class="po-detail-list"><div><span>Programme</span><strong><?= e($c['programme_name']) ?></strong></div><div><span>Programme Type</span><strong><?= e((string)($c['programme_type']??'—')) ?></strong></div><div><span>Cohort</span><strong><?= e($c['cohort_name']) ?></strong></div><div><span>Cohort Status</span><strong><?= e(po_status_label($c['cohort_status'])) ?></strong></div><div><span>Cohort Start</span><strong><?= e(po_date($c['cohort_start_date'])) ?></strong></div><div><span>Cohort End</span><strong><?= e(po_date($c['cohort_end_date'])) ?></strong></div></div></div></section><section class="po-card"><div class="po-card__header"><div><h3>Candidate Timeline</h3><p>Recorded participation milestones.</p></div></div><div class="po-card__body"><div class="po-timeline"><?php foreach([['Selected',$c['selected_at']],['Onboarded',$c['onboarded_at']],['Completed',$c['completed_at']]] as $t):?><div class="po-timeline__item <?= $t[1]?'is-complete':'' ?>"><span class="po-timeline__dot"><i class="fas fa-check"></i></span><div><strong><?= e($t[0]) ?></strong><span><?= e(po_datetime($t[1])) ?></span></div></div><?php endforeach;?></div></div></section></div>
<div class="po-security"><i class="fas fa-shield-halved"></i><div><strong>Read-only candidate view</strong><span>This page deliberately does not expose reassignment or status-change controls until your exact Programme Officer permissions are confirmed.</span></div></div>
<?php require __DIR__.'/_layout_end.php';?>
